/// <summary>
/// The <c>ConDemoPostingService</c> class exposes a code path that is gated by the fast posting feature.
/// </summary>
public final class ConDemoPostingService
{
}

Method.Source:
/// <summary>
/// Describes the posting path that is currently active.
/// </summary>
/// <returns>A labelled description of the active posting path.</returns>
public static str describe()
{
    if (FeatureStateProvider::isFeatureEnabled(ConDemoFastPostingFeature::instance()))
    {
        return "@Contoso:DemoPostingFastDescription";
    }

    return "@Contoso:DemoPostingStandardDescription";
}
